code.cpp:
class Solution {
public:
    int digArtifacts(int n, vector<vector<int>>& artifacts, vector<vector<int>>& dig) {
        unordered_set<int> dug;
        for (auto& d : dig) {
            dug.insert(d[0] * n + d[1]);
        }
        int count = 0;
        for (auto& a : artifacts) {
            bool allDug = true;
            for (int r = a[0]; r <= a[2] && allDug; r++) {
                for (int c = a[1]; c <= a[3] && allDug; c++) {
                    if (!dug.count(r * n + c)) {
                        allDug = false;
                    }
                }
            }
            if (allDug) count++;
        }
        return count;
    }
};
